"""Bind each once-owned strip to its Street and live adjacent patch providers."""
import bpy
from . import curved_patch_provider_bindings as patches
from . import curved_network_input_nodes,curved_network_surface_nodes,curved_strip_provider_nodes


def install(obj,*,provider_tree=None,network_tree=None,collection=None,interpolation=False):
    if len(obj.data.vertices):raise ValueError('Controller-base sources need an explicit dependency adapter')
    tables=patches.input_values(obj)
    if not tables.get('Patch Results'):raise ValueError('Strip caching requires existing patch providers')
    if tables.get('Strip Results'):raise ValueError('Strip providers are already installed')
    collection=collection or bpy.context.scene.collection
    private=bpy.data.collections.new(obj.name+' / strip inputs');collection.children.link(private)
    providers=bpy.data.collections.new(obj.name+' / strip providers');collection.children.link(providers)
    root=provider_tree or curved_network_input_nodes.build(curved_strip_provider_nodes.build(interpolation=interpolation),
        scoped_sources=True,apply_material=False,interpolation=interpolation)
    by_site={site:owner for owner,sites in patches.owner_sites(tables).items() for site in sites}
    by_owner={int(p['st_cached_patch_owner']):p for p in tables['Patch Results'].objects}
    if len(by_owner)!=len(tables['Patch Results'].objects):raise ValueError('Repeated patch owner')
    junctions=tables['Junctions'].data;incidence_site={}
    for site,(start,count) in enumerate(zip(patches.values(junctions,'st_cj_range_start'),patches.values(junctions,'st_cj_range_count'))):
        incidence_site.update({i:site for i in range(start,start+count)})
    rows=[]
    for kind,key,prefix,ends in ((1,'Corridors','st_cs_',('start_index','end_index')),
                                (3,'External Approaches','st_ca_',('start_index',))):
        table=tables[key].data
        for at,sid in enumerate(patches.values(table,prefix+'street_id')):
            label=obj.name+(' / Corridor ' if kind==1 else ' / Free approach ')+str(at).zfill(3)
            inputs,deps=patches.scope(obj,tables,(),private,label,required_streets=(sid,))
            owners=sorted({by_site[incidence_site[patches.values(table,prefix+end)[at]]] for end in ends})
            adjacent=bpy.data.collections.new(label+' mouths');private.children.link(adjacent)
            for owner in owners:adjacent.objects.link(by_owner[owner])
            part=bpy.data.objects.new(label,bpy.data.meshes.new(label+' input'));providers.objects.link(part)
            part.parent=obj;part.modifiers.new('Shared cached strip owner','NODES').node_group=root
            part.modifiers[0].show_viewport=False
            patches.set_inputs(part,dict(tables,**inputs,**{'Patch Results':adjacent,'Owner Index':at,'Owner Kind':kind}))
            part.hide_set(True);part.hide_render=True;part['st_cached_strip_owner']=at;part['st_cached_strip_kind']=kind
            part.modifiers[0].show_viewport=True
            rows.append(dict(index=at,kind=kind,street_id=sid,patch_owners=owners,dependencies=deps,object=part.name))
    previous=obj.modifiers[0].node_group
    if network_tree is None:
        core=curved_network_surface_nodes.build(tapered=True,external=True,regularize_mouths=True,
            exact_mouths=True,local_frames=True,dimensions=True,compounds=True,general_patches=True,
            port_paths=True,logical_clusters=True,cached_patches=True,cached_strips=True,interpolation=interpolation)
